js='''const cards=[...document.querySelectorAll('article')],search=document.querySelector('#search'),group=document.querySelector('#group'),status=document.querySelector('#status'),key='kabita-likeness-holds-review-2026-10-04';let notes={};try{notes=JSON.parse(localStorage.getItem(key)||'{}')}catch{}function filter(){let n=0;cards.forEach(c=>{c.hidden=!(c.dataset.search.includes(search.value.toLowerCase())&&(group.value==='all'||c.dataset.group===group.value));if(!c.hidden)n++});status.textContent=n+' of 35 writers shown';document.querySelector('#empty').hidden=n>0}search.addEventListener('input',filter);group.addEventListener('change',filter);document.querySelectorAll('[data-filter]').forEach(a=>a.addEventListener('click',()=>{group.value=a.dataset.filter;search.value='';filter()}));function save(){try{localStorage.setItem(key,JSON.stringify(notes));document.querySelector('#saved').textContent='Notes saved in this browser only.'}catch{document.querySelector('#saved').textContent='Browser storage unavailable. Export notes before leaving.'}}cards.forEach(c=>{const s=c.querySelector('select'),t=c.querySelector('textarea'),id=c.dataset.id;s.value=notes[id]?.decision||'';t.value=notes[id]?.note||'';function changed(){notes[id]={name:c.querySelector('h2').textContent,decision:s.value,note:t.value};save()}s.addEventListener('change',changed);t.addEventListener('input',changed)});const exportDialog=document.querySelector('#notes-export'),exportText=document.querySelector('#export-text');document.querySelector('#export').addEventListener('click',()=>{exportText.value=JSON.stringify({review:'Kabita Live likeness holds',exported_at:new Date().toISOString(),scope:'Review preferences only; no site changes authorized or applied by this page',notes},null,2);exportDialog.showModal()});document.querySelector('#close-export').addEventListener('click',()=>exportDialog.close());document.querySelector('#select-export').addEventListener('click',()=>{exportText.focus();exportText.select()});document.querySelector('#save-export').addEventListener('click',()=>{const blob=new Blob([exportText.value],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='kabita-likeness-review-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});const dialog=document.querySelector('dialog');document.querySelectorAll('.image-button').forEach(b=>b.addEventListener('click',()=>{const im=b.querySelector('img');dialog.querySelector('img').src=im.src;dialog.querySelector('img').alt=im.alt;dialog.querySelector('p').textContent=im.alt;dialog.showModal()}));dialog.querySelector('button').addEventListener('click',()=>dialog.close());filter();if(location.hash){const c=document.getElementById(location.hash.slice(1));if(c?.matches('article'))c.scrollIntoView()}'''
header=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>35 portrait holds · Kabita Live review</title><style>{style}</style></head><body><main id="top"><span class="eyebrow">Kabita Live · private working review · 4 October 2026</span><h1>Why these 35 portraits are on hold.</h1><p class="intro">Every writer here still uses their original photograph. A “likeness hold” means the watercolor could not be verified confidently under our source-faithful rules. It does not always mean the face looks like a different person.</p><div class="notice"><b>Two different kinds of uncertainty.</b> Some photos lack enough detail to verify a painted face. Other photos are usable, but the generated artwork adds or changes something: a crop, ornament, skin mark or colour. Several of these are conservative detail-level holds that you may judge acceptable when you compare the images.</div><div class="stats">{''.join(f'<a href="#review-list" data-filter="{g}"><b>{len(ids)}</b>{esc(label)}</a>' for g,(label,ids) in groups.items())}</div><p>These are primary reasons; some portraits have more than one issue. <b>23 writers have saved candidates; 12 were held before generation.</b> The three missing-photo profiles now using generic artwork are separate and are not included here.</p><p><b>How to review:</b> compare at normal size first, then click an image to enlarge its review preview. The original is always first; attempts are unused. Read “What to compare” below each set. The explanations summarize the saved self-review notes; this page is not an independent author/editor judgment.</p><p>Choose a review preference and add notes if useful. They stay in this browser; <b>Export notes</b> shows a copy you can select or download and share back. Choosing an attempt does not change a poet’s page or publish it.</p><div class="controls" id="review-list"><label>Find a writer<input id="search" type="search" placeholder="Name or writer ID"></label><label>Reason<select id="group"><option value="all">All holds</option>{''.join(f'<option value="{g}">{esc(label)}</option>' for g,(label,_) in groups.items())}</select></label><button id="export" type="button">Export notes</button><span id="status" role="status"></span></div><p id="saved" class="status">Review notes have not been changed in this visit.</p><p id="empty" class="empty" hidden>No writers match. Clear the search or choose All holds.</p>'''
(OUT/'index.html').write_text(header+''.join(cards)+f'<a class="toplink" href="#top">Back to top ↑</a><p class="technical">Frozen review set after portrait-079. Source and master files are preserved; review previews are resized only, never retouched. Exact originals, candidate paths, hashes and saved concerns are recorded in the accompanying manifest. All 35 currently use the original journal photograph. No portraits were regenerated or replaced for this review.</p></main><dialog aria-label="Enlarged portrait preview"><button type="button">Close preview</button><img alt=""><p></p></dialog><dialog id="notes-export" aria-label="Export review notes"><button id="close-export" type="button">Close export</button><h2>Your review notes</h2><p>Copy this text back into the chat, or save a file. This does not apply any portrait changes.</p><label for="export-text">Review notes to copy</label><textarea id="export-text" rows="14" readonly style="min-width:min(680px,78vw)"></textarea><button id="select-export" type="button">Select text</button><button id="save-export" type="button">Save JSON file</button></dialog><script>{js}</script></body></html>')
